mapper.update:
update pay_order set status = 'MARKET', update_time = now() where order_id in
#{orderId}
and status = 'PAY_SUCCESS'

mapper.select:
select user_id, product_id, product_code, product_name, order_id, order_time, total_amount, status, pay_url, market_type, market_deduction_amount, pay_amount
from pay_order
where order_id = #{orderId}

select id, user_id, product_id, product_code, product_name, order_id, order_time, total_amount, status, pay_url, pay_time, market_type, market_deduction_amount, pay_amount
from pay_order
where user_id = #{userId}

    and id > #{lastId}

order by id asc
limit #{pageSize}

select id, user_id, product_id, product_code, product_name, order_id, order_time, total_amount, status, pay_url, pay_time, market_type, market_deduction_amount, pay_amount
from pay_order
where user_id = #{userId} and order_id = #{orderId}
